// The one place to change settings for this workflow.
return [{
  json: {
    cf_account: 'YOUR_CLOUDFLARE_ACCOUNT_ID',
    d1_database: 'YOUR_D1_DATABASE_ID', // the marketing Worker's D1 database
    hermes_url: 'http://hermes:8642/v1/chat/completions', // Hermes in the same Docker network as n8n
    hermes_model: 'hermes-agent', // Hermes answers with its own configured model chain
    session_key: 'daily-analyst', // Hermes keeps this report's memory under this name
    timezone: 'Asia/Dubai',

    // What Hermes needs to suggest useful improvements. Your words; update it when your focus changes.
    goals: `NB-Systems builds custom business software (POS, gas station and distributor systems, websites and apps)
for small businesses in Lebanon. Website: nb-systems.naja.live, with live demos and an AI assistant (Shater).
Main goal now: the first paying clients. Channels: Facebook, Instagram and LinkedIn posts, the website, WhatsApp, referrals.
Leads come from the contact form, demo signups and quote requests. A demo being woken by a visitor means real interest.

Things to know (don't suggest against these without saying why):
- LinkedIn posts go to the owner's personal profile. LinkedIn gives no results for those, so LinkedIn numbers are always 0. Ignore them.
- The demos run on Render's free tier on purpose (no cost). They sleep when unused and a visitor wakes them. Frequent pings
  or uptime monitors would use up Render's 750 free hours a month, so never suggest pinging. "Refused" means Render's
  wake-up limit, not a broken app. The owner also has a free, always-on Oracle Cloud server (24 GB RAM) that could host them.
- AutoServicePro is sold and supported by the partner Khulasa Systems, not by NB-Systems. Don't suggest work on it.
- Posts are prepared once a month in a batch and scheduled; the automation only publishes them.`,
  },
}];

// Turns every data source into one small summary for Hermes: totals and statuses only.
// No lead names, emails or messages ever leave this node (free AI tiers may learn from what they receive).
const s = $('Settings').first().json;
const DAY = 86_400_000;
const now = Date.now();
const rows = (node) => {
  try { return $(node).all().map((i) => i.json).filter((r) => r && Object.keys(r).length && !r.error); } catch { return []; }
};
const d1 = (node) => {
  try { const j = $(node).first().json; return j.error ? [] : j.result?.[0]?.results ?? []; } catch { return []; }
};
const sum = (list, k) => list.reduce((t, r) => t + (Number(r[k]) || 0), 0);
const iso = (ms) => (ms ? new Date(ms).toISOString() : null);

// ---------- leads and demos (Supabase) ----------
const biz = rows('Leads & demos')[0] ?? {};

// ---------- workflows (n8n's own execution log) ----------
const runs = rows('Workflow runs (24h)');
const workflows = runs.map((r) => ({ name: r.name, runs: Number(r.runs), failed: Number(r.failed), last_failure: r.last_failure }));

// ---------- marketing (Cloudflare D1) ----------
const targets = d1('D1: posts (14 days)');
const inWindow = (r, from, to) => r.posted_at && r.posted_at >= from && r.posted_at < to;
const platformStats = (from, to) => {
  const out = {};
  for (const r of targets.filter((t) => t.status === 'posted' && inWindow(t, from, to))) {
    const p = (out[r.platform] ??= { posts: 0, reach: 0, views: 0, likes: 0, comments: 0, shares: 0, saves: 0 });
    p.posts++;
    for (const k of ['reach', 'views', 'likes', 'comments', 'shares', 'saves']) p[k] += Number(r[k]) || 0;
  }
  return out;
};
const failed = targets
  .filter((t) => t.status === 'failed' && t.updated_at >= now - DAY)
  .map((t) => ({ post: t.post_id, platform: t.platform, attempts: t.attempts, error: String(t.error ?? '').slice(0, 160) }));
const retrying = targets
  .filter((t) => (t.status === 'pending' || t.status === 'processing') && t.attempts > 0)
  .map((t) => ({ post: t.post_id, platform: t.platform, attempts: t.attempts, error: String(t.error ?? '').slice(0, 160) }));
const posted24h = targets.filter((t) => t.status === 'posted' && t.posted_at >= now - DAY).map((t) => `${t.post_id}/${t.platform}`);
const upcoming = d1('D1: upcoming posts');

const jobs = d1('D1: automatic jobs').map((j) => ({
  job: j.job,
  last_run: iso(j.ran_at),
  hours_ago: Math.round((now - j.ran_at) / 3_600_000),
  ok: !!j.ok,
  runner: j.runner === 'n8n' ? 'n8n' : 'Cloudflare Worker',
}));

const facts = {
  date: new Intl.DateTimeFormat('en-GB', { timeZone: s.timezone, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }).format(now),
  timezone: s.timezone,
  marketing: {
    posted_last_24h: posted24h,
    failed_last_24h: failed,
    retrying_now: retrying,
    results_last_7d: platformStats(now - 7 * DAY, now),
    results_previous_7d: platformStats(now - 14 * DAY, now - 7 * DAY),
    scheduled_next_7d: upcoming.map((u) => ({ post: u.id, when: iso(u.scheduled_at), status: u.status })),
  },
  leads: {
    new_last_24h: biz.leads_new_24h ?? null,
    spam_last_24h: biz.leads_spam_24h ?? null,
    new_last_7d: biz.leads_new_7d ?? null,
    new_previous_7d: biz.leads_new_prev_7d ?? null,
    waiting_for_reply: biz.leads_waiting ?? null,
    by_source_last_7d: biz.leads_by_source_7d ?? {},
  },
  demos: {
    latest_check: biz.demos_latest ?? [],
    uptime_7d_pct: biz.demos_uptime_7d ?? {},
    alerts_last_24h: biz.demo_alerts_24h ?? [],
  },
  automations: {
    workflows_last_24h: workflows,
    scheduled_jobs: jobs,
    data_missing: [
      !Object.keys(biz).length && 'leads and demos (Supabase query failed)',
      !runs.length && 'n8n workflow runs (query failed or nothing ran)',
      !targets.length && !jobs.length && 'marketing (D1 query failed)',
    ].filter(Boolean),
  },
};

// Loud notification only when something needs action today.
const urgent =
  failed.length > 0 ||
  workflows.some((w) => w.failed > 0) ||
  (facts.demos.latest_check || []).some((d) => d.ok === false) ||
  jobs.some((j) => !j.ok || (j.job === 'publish' && j.runner !== 'n8n'));

// Plain fallback text, used only if Hermes can't be reached.
const fallback = [
  `Leads: ${facts.leads.new_last_24h ?? '?'} new in 24h, ${facts.leads.waiting_for_reply ?? '?'} waiting for a reply`,
  `Posts: ${posted24h.length} published, ${failed.length} failed in 24h, ${upcoming.length} scheduled this week`,
  `Demos: ${(facts.demos.latest_check || []).filter((d) => d.ok === false).map((d) => d.demo).join(', ') || 'all up'} ${(facts.demos.latest_check || []).some((d) => d.ok === false) ? 'down' : ''}`.trim(),
  `Workflows: ${workflows.filter((w) => w.failed > 0).map((w) => `${w.name} (${w.failed} failed)`).join(', ') || 'no failures'}`,
].join('\n');

const weekly = new Intl.DateTimeFormat('en-GB', { timeZone: s.timezone, weekday: 'long' }).format(now) === 'Monday';

// What Hermes is asked. Plain text out (no HTML/markdown), so Telegram can't reject the message.
const instructions = `You are the operations analyst for NB-Systems, a small software company in Lebanon.
Every morning you get the facts below and write the daily report the owner reads on Telegram.

Rules:
- Use only the numbers in the facts. Never invent or estimate numbers.
- Plain text only: no markdown, no asterisks, no HTML. Short lines. Emojis only as section markers.
- At most 18 lines (25 on Mondays). Sections, in this order, skipping any with nothing to say:
  1. One status line. Write "All good" only if "Needs attention" would be empty; otherwise name the most important
     problem in a few words (for example "4 demos down, no leads this week").
  2. Needs attention: failed posts, workflow failures, demos down, jobs that failed or are overdue. Say what to do.
  3. Marketing: what was posted, results vs the previous 7 days (up or down, with numbers).
  4. Leads: new leads and how many wait for a reply. Compare with the previous 7 days.
  5. Demos and automations: one line unless something is wrong.
- Context you can rely on: the "publish" job is expected to run on n8n; if it shows the Cloudflare Worker, n8n stopped and the
  Worker took over, which needs attention. The other scheduled jobs still run on the Cloudflare Worker by design (for now).
- Then one line starting "Idea:" with one concrete way to improve the business, based on today's facts and the goals
  below (for example which kind of post worked best, a lead source to push, a demo to fix first). Not generic advice.
${weekly ? `- It is Monday: after the Idea line, add "Weekly review:" with 3 short, specific improvements for this week,
  one each for marketing, getting leads, and the demos or automations. Base them on the last 7 days and on your memory.\n` : ''}- End with one line starting "Today:" with the single most useful action.
- Memory: before writing, check your memory for earlier reports and ideas. Mention real trends (for example a third day
  without leads) and follow up on earlier ideas when the numbers show their effect. Never repeat an idea you gave in
  the last 7 days. After writing, save one short memory note: today's key numbers, the idea you gave, anything to watch.

Business and goals (from the owner):
${s.goals}`;

const request = {
  model: s.hermes_model,
  messages: [
    { role: 'system', content: instructions },
    { role: 'user', content: `Facts for today (JSON):\n${JSON.stringify(facts)}` },
  ],
};

return [{ json: { facts, urgent, fallback, request } }];

// The Telegram message: Hermes' report, or the plain numbers if Hermes couldn't answer (so a report always arrives).
const sum = $('Build summary').first().json;
const res = $json;
const reply = String(res?.choices?.[0]?.message?.content ?? '').trim();
const date = sum.facts.date;

const text = reply
  ? `🧠 Daily report · ${date}\n\n${reply}`
  : `🧠 Daily report · ${date}\n\n⚠️ Hermes couldn't write today's report (${String(res?.error?.message ?? res?.error ?? 'no answer').slice(0, 200)}). The numbers:\n\n${sum.fallback}`;

// Telegram's limit is 4096 characters.
return [{ json: { text: text.slice(0, 4000), silent: !sum.urgent && !!reply } }];
